// TypeScript port of ml/prompt.py (build_messages). Text must stay identical: prompted Gemma, the LoRA training data and this file share one prompt.
// Parity is enforced by prompt.test.ts against a golden file generated by python3 ml/prompt.py.
// Python json.dumps details kept here: the schema is dumped with separators (",", ":") and ensure_ascii=True;
// the user message is dumped with Python's default separators (", ", ": ") and ensure_ascii=False. Key order is insertion order.
// Research prototype. Not a medical device. Not for clinical use.
import lungSchema from './schemas/lung.json';
import colorectalSchema from './schemas/colorectal.json';
import ovarianSchema from './schemas/ovarian.json';

export type CancerName = 'lung' | 'colorectal' | 'ovarian';

const SCHEMAS: Record<CancerName, unknown> = { lung: lungSchema, colorectal: colorectalSchema, ovarian: ovarianSchema };

/** Same text as SYSTEM_TEMPLATE in ml/prompt.py with the {schema} placeholder at the end. */
const SYSTEM_PREFIX = `You fill a GP Referral template from free-text GP notes. The notes may be English or Finnish.
Return ONE JSON object, no prose, no code fence: {"fields": {...}, "evidence": {...}}.
- "fields" must validate against the JSON Schema below. Use only facts in the notes or recordFacts. Never invent.
- If a required value is not in the notes, use null. If an optional field is not in the notes, leave it out.
- Write every free-text value in "fields" in English, even when the notes are Finnish (translate faithfully).
- "evidence" maps a field name to the exact words copied from the notes that justify it, in the notes' own language. Skip fields taken from recordFacts.
- Dates are YYYY-MM-DD. This is a research prototype with made-up patients.

JSON Schema:
`;

export interface EarlierNote {
  date: string;
  note: string;
}

export interface RecordFacts {
  patientId: string;
  age: number;
  sex: string;
  referralDate: string;
  referringGpId: string;
}

export interface ChatMessage {
  role: 'system' | 'user';
  content: string;
}

/** Python json.dumps for the JSON values used here (strings, integers, booleans, null, lists, dicts). */
export function pyDumps(value: unknown, ensureAscii: boolean, sep: { item: string; kv: string }): string {
  if (value === null) return 'null';
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number') {
    if (!Number.isInteger(value)) throw new Error('pyDumps: only integers are supported (Python float repr differs)');
    return String(value);
  }
  if (typeof value === 'string') {
    const s = JSON.stringify(value);
    // Python ensure_ascii escapes everything outside printable ASCII as \uXXXX (lowercase, UTF-16 units like JS).
    return ensureAscii ? s.replace(/[^\x20-\x7e]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`) : s;
  }
  if (Array.isArray(value)) return `[${value.map((x) => pyDumps(x, ensureAscii, sep)).join(sep.item)}]`;
  if (typeof value === 'object') {
    const parts = Object.entries(value as Record<string, unknown>)
      .filter(([, v]) => v !== undefined)
      .map(([k, v]) => `${pyDumps(k, ensureAscii, sep)}${sep.kv}${pyDumps(v, ensureAscii, sep)}`);
    return `{${parts.join(sep.item)}}`;
  }
  throw new Error(`pyDumps: unsupported value type ${typeof value}`);
}

/** The schema text as build_messages inserts it: json.dumps(schema, separators=(",", ":")). */
export function schemaText(cancer: CancerName): string {
  return pyDumps(SCHEMAS[cancer], true, { item: ',', kv: ':' });
}

/** Port of build_messages(cancer, today_note, earlier_notes, record_facts). */
export function buildMessages(cancer: CancerName, todayNote: string, earlierNotes: EarlierNote[], recordFacts: RecordFacts): ChatMessage[] {
  const user = {
    cancer,
    todayNote,
    earlierNotes: earlierNotes.map((e) => ({ date: e.date, note: e.note })),
    recordFacts: {
      patientId: recordFacts.patientId,
      age: recordFacts.age,
      sex: recordFacts.sex,
      referralDate: recordFacts.referralDate,
      referringGpId: recordFacts.referringGpId,
    },
  };
  return [
    { role: 'system', content: SYSTEM_PREFIX + schemaText(cancer) },
    { role: 'user', content: pyDumps(user, false, { item: ', ', kv: ': ' }) },
  ];
}
